struct algorithm
{
    struct object     hdr;
    enum alg_id       id;
    enum chain_mode   chain_mode;
    ULONG             flags;
    enum ecc_curve_id curve_id;
};

struct asymmetric_key
{
    ULONG bitlen;     /* key strength for ECC keys */
    union
    {
        struct rsa_key rsa;
        struct ecc_key ecc;
        struct dsa_key dsa;
    };
};

struct dsa_key
{
    SYMCRYPT_DLKEY   *handle;
    SYMCRYPT_DLGROUP *group;
    UCHAR             seed[20];
    UINT32            count;
};

struct ecc_key
{
    SYMCRYPT_ECKEY   *handle;
    SYMCRYPT_ECURVE  *curve;
    enum ecc_curve_id curve_id;
};

struct key
{
    struct object hdr;
    enum alg_id   alg_id;
    ULONG         flags;
    union
    {
        struct symmetric_key s;
        struct asymmetric_key a;
    };
};

union
{
    struct rsa_key rsa;
    struct ecc_key ecc;
    struct dsa_key dsa;
};

union
{
    struct symmetric_key s;
    struct asymmetric_key a;
};
